// Process character update request
const characterData = $input.first().json;
const { 
  characterId,
  action, // 'update', 'create', 'get', 'delete'
  hpChange = 0,
  mpChange = 0,
  xpGain = 0,
  conditionChanges = [],
  inventoryChanges = [],
  spellUsage = [],
  stats = {}
} = characterData;

// Validate required fields
if (!characterId || !action) {
  throw new Error('Missing required fields: characterId, action');
}

// Prepare operation data
const operationData = {
  characterId,
  action,
  timestamp: new Date().toISOString(),
  hpChange,
  mpChange,
  xpGain,
  conditionChanges,
  inventoryChanges,
  spellUsage,
  stats,
  metadata: {
    processedBy: 'character-state-workflow',
    version: '1.0'
  }
};

return { json: operationData };

// Calculate character stat updates and HP/MP regeneration
const characterData = $input.first().json;
const { 
  hpChange,
  mpChange,
  xpGain,
  conditionChanges,
  inventoryChanges,
  spellUsage
} = characterData;

// Get current character data (if updating)
let currentStats = {};
if ($input.length > 1 && $input[1].json && $input[1].json.values) {
  const headerRow = $input[1].json.values[0];
  const dataRow = $input[1].json.values.find(row => row[0] === characterData.characterId);

  if (dataRow) {
    currentStats = {
      characterId: dataRow[0],
      name: dataRow[1],
      level: parseInt(dataRow[2]) || 1,
      class: dataRow[3] || '',
      hpCurrent: parseInt(dataRow[4]) || 0,
      hpMax: parseInt(dataRow[5]) || 100,
      mpCurrent: parseInt(dataRow[6]) || 0,
      mpMax: parseInt(dataRow[7]) || 50,
      xpCurrent: parseInt(dataRow[8]) || 0,
      xpToNext: parseInt(dataRow[9]) || 1000,
      conditions: dataRow[10] || '',
      inventoryWeight: parseFloat(dataRow[11]) || 0,
      inventoryValue: parseFloat(dataRow[12]) || 0,
      spellSlotsUsed: parseInt(dataRow[13]) || 0,
      spellSlotsMax: parseInt(dataRow[14]) || 3,
      lastUpdated: dataRow[15] || new Date().toISOString()
    };
  }
}

// Calculate new HP/MP with bounds checking
const newHpCurrent = Math.max(0, Math.min(
  currentStats.hpMax || 100,
  (currentStats.hpCurrent || 0) + hpChange
));

const newMpCurrent = Math.max(0, Math.min(
  currentStats.mpMax || 50,
  (currentStats.mpCurrent || 0) + mpChange
));

// Handle XP and level progression
let newXpCurrent = (currentStats.xpCurrent || 0) + xpGain;
let newLevel = currentStats.level || 1;
let xpToNext = currentStats.xpToNext || 1000;

// Level up logic
while (newXpCurrent >= xpToNext) {
  newXpCurrent -= xpToNext;
  newLevel++;
  xpToNext = Math.floor(xpToNext * 1.2); // 20% increase per level
}

// Update conditions
let currentConditions = (currentStats.conditions || '').split(',').filter(c => c.trim());
conditionChanges.forEach(change => {
  const { condition, action: condAction } = change;
  if (condAction === 'add' && !currentConditions.includes(condition)) {
    currentConditions.push(condition);
  } else if (condAction === 'remove') {
    currentConditions = currentConditions.filter(c => c !== condition);
  }
});

// Update inventory weight/value (simplified calculation)
let inventoryWeight = currentStats.inventoryWeight || 0;
let inventoryValue = currentStats.inventoryValue || 0;
inventoryChanges.forEach(change => {
  const { action: invAction, weight = 0, value = 0 } = change;
  if (invAction === 'add') {
    inventoryWeight += weight;
    inventoryValue += value;
  } else if (invAction === 'remove') {
    inventoryWeight = Math.max(0, inventoryWeight - weight);
    inventoryValue = Math.max(0, inventoryValue - value);
  }
});

// Update spell slots
let spellSlotsUsed = currentStats.spellSlotsUsed || 0;
spellUsage.forEach(usage => {
  if (usage.action === 'cast') {
    spellSlotsUsed += usage.slots || 1;
  } else if (usage.action === 'restore') {
    spellSlotsUsed = Math.max(0, spellSlotsUsed - (usage.slots || 1));
  }
});

// Prepare updated character data
const updatedCharacter = {
  characterId: characterData.characterId,
  name: currentStats.name || 'Unknown',
  level: newLevel,
  class: currentStats.class || '',
  hpCurrent: newHpCurrent,
  hpMax: currentStats.hpMax || 100,
  mpCurrent: newMpCurrent,
  mpMax: currentStats.mpMax || 50,
  xpCurrent: newXpCurrent,
  xpToNext: xpToNext,
  conditions: currentConditions.join(', '),
  inventoryWeight: Math.round(inventoryWeight * 100) / 100,
  inventoryValue: Math.round(inventoryValue * 100) / 100,
  spellSlotsUsed: spellSlotsUsed,
  spellSlotsMax: currentStats.spellSlotsMax || 3,
  lastUpdated: new Date().toISOString(),
  metadata: {
    hpChange,
    mpChange,
    xpGain,
    leveledUp: newLevel > (currentStats.level || 1),
    processedBy: 'character-calculations'
  }
};

return { json: updatedCharacter };

// Format character data for Google Sheets
const characterData = $input.first().json;

// Prepare row data in the correct order for Google Sheets
const rowData = [
  characterData.characterId,
  characterData.name,
  characterData.level,
  characterData.class,
  characterData.hpCurrent,
  characterData.hpMax,
  characterData.mpCurrent,
  characterData.mpMax,
  characterData.xpCurrent,
  characterData.xpToNext,
  characterData.conditions,
  characterData.inventoryWeight,
  characterData.inventoryValue,
  characterData.spellSlotsUsed,
  characterData.spellSlotsMax,
  characterData.lastUpdated
];

return {
  json: {
    range: 'Character_State!A:P',
    values: [rowData]
  }
};

// Send real-time character update to WebSocket system
const characterData = $input.first().json;
const { characterId, metadata } = characterData;

// Prepare WebSocket broadcast payload
const broadcastPayload = {
  type: 'character_update',
  data: {
    characterId,
    updates: {
      hp: {
        current: characterData.hpCurrent,
        max: characterData.hpMax,
        change: metadata.hpChange || 0
      },
      mp: {
        current: characterData.mpCurrent,
        max: characterData.mpMax,
        change: metadata.mpChange || 0
      },
      xp: {
        current: characterData.xpCurrent,
        toNext: characterData.xpToNext,
        gain: metadata.xpGain || 0,
        leveledUp: metadata.leveledUp || false
      },
      conditions: characterData.conditions,
      inventory: {
        weight: characterData.inventoryWeight,
        value: characterData.inventoryValue
      },
      spellSlots: {
        used: characterData.spellSlotsUsed,
        max: characterData.spellSlotsMax
      },
      level: characterData.level
    },
    timestamp: new Date().toISOString()
  },
  channels: [`character_${characterId}`, 'game_updates']
};

// Send to WebSocket system
fetch('http://localhost:5678/webhook/websocket/broadcast', {
  method: 'POST',
  headers: {
    'Content-Type': 'application/json'
  },
  body: JSON.stringify(broadcastPayload)
}).catch(error => {
  console.error('Failed to broadcast character update:', error);
});

return { json: { broadcast: 'sent', characterId } };

