// Process character regeneration request
const regenData = $input.first().json;
const { 
  characterId,
  hpRegenRate = 0.05, // 5% of max HP per interval
  mpRegenRate = 0.10, // 10% of max MP per interval
  intervalMinutes = 5 // Default 5-minute intervals
} = regenData;

// Get current character data from Google Sheets
const sheetId = $vars.GOOGLE_SHEETS_CHARACTER_SHEET_ID;
const range = 'Character_State!A:P';

// This would typically be a Google Sheets lookup
// For now, simulate getting current character data
return {
  json: {
    characterId,
    hpRegenRate,
    mpRegenRate,
    intervalMinutes,
    action: 'regeneration',
    timestamp: new Date().toISOString()
  }
};

// Calculate regeneration amounts
const characterData = $input.first().json;
const { hpRegenRate, mpRegenRate } = characterData;

// Get current character stats
let currentStats = { hpCurrent: 0, hpMax: 100, mpCurrent: 0, mpMax: 50 };
if ($input.length > 1 && $input[1].json && $input[1].json.values) {
  const dataRow = $input[1].json.values.find(row => row[0] === characterData.characterId);
  if (dataRow) {
    currentStats = {
      hpCurrent: parseInt(dataRow[4]) || 0,
      hpMax: parseInt(dataRow[5]) || 100,
      mpCurrent: parseInt(dataRow[6]) || 0,
      mpMax: parseInt(dataRow[7]) || 50
    };
  }
}

// Calculate regeneration amounts
const hpRegenAmount = Math.floor(currentStats.hpMax * hpRegenRate);
const mpRegenAmount = Math.floor(currentStats.mpMax * mpRegenRate);

// Apply regeneration with bounds checking
const newHpCurrent = Math.min(
  currentStats.hpMax,
  currentStats.hpCurrent + hpRegenAmount
);

const newMpCurrent = Math.min(
  currentStats.mpMax,
  currentStats.mpCurrent + mpRegenAmount
);

// Prepare regeneration data
const regenerationData = {
  characterId: characterData.characterId,
  hpChange: newHpCurrent - currentStats.hpCurrent,
  mpChange: newMpCurrent - currentStats.mpCurrent,
  hpRegenAmount,
  mpRegenAmount,
  action: 'update',
  timestamp: new Date().toISOString()
};

return { json: regenerationData };

// Data validation for character operations
const characterData = $input.first().json;
const validationErrors = [];

// Validate character ID format
if (!characterData.characterId || typeof characterData.characterId !== 'string') {
  validationErrors.push('Invalid character ID format');
}

// Validate HP values
if (characterData.hpCurrent !== undefined) {
  if (typeof characterData.hpCurrent !== 'number' || characterData.hpCurrent < 0) {
    validationErrors.push('HP current must be a non-negative number');
  }
}
if (characterData.hpMax !== undefined) {
  if (typeof characterData.hpMax !== 'number' || characterData.hpMax <= 0) {
    validationErrors.push('HP max must be a positive number');
  }
}

// Validate MP values
if (characterData.mpCurrent !== undefined) {
  if (typeof characterData.mpCurrent !== 'number' || characterData.mpCurrent < 0) {
    validationErrors.push('MP current must be a non-negative number');
  }
}
if (characterData.mpMax !== undefined) {
  if (typeof characterData.mpMax !== 'number' || characterData.mpMax < 0) {
    validationErrors.push('MP max must be a non-negative number');
  }
}
// Validate XP values
if (characterData.xpCurrent !== undefined) {
  if (typeof characterData.xpCurrent !== 'number' || characterData.xpCurrent < 0) {
    validationErrors.push('XP current must be a non-negative number');
  }
}

// Validate level
if (characterData.level !== undefined) {
  if (typeof characterData.level !== 'number' || characterData.level < 1 || characterData.level > 100) {
    validationErrors.push('Level must be a number between 1 and 100');
  }
}

// Validate inventory weight/value
if (characterData.inventoryWeight !== undefined) {
  if (typeof characterData.inventoryWeight !== 'number' || characterData.inventoryWeight < 0) {
    validationErrors.push('Inventory weight must be a non-negative number');
  }
}
if (characterData.inventoryValue !== undefined) {
  if (typeof characterData.inventoryValue !== 'number' || characterData.inventoryValue < 0) {
    validationErrors.push('Inventory value must be a non-negative number');
  }
}

// Validate spell slots
if (characterData.spellSlotsUsed !== undefined) {
  if (typeof characterData.spellSlotsUsed !== 'number' || characterData.spellSlotsUsed < 0) {
    validationErrors.push('Spell slots used must be a non-negative number');
  }
}
if (characterData.spellSlotsMax !== undefined) {
  if (typeof characterData.spellSlotsMax !== 'number' || characterData.spellSlotsMax < 0) {
    validationErrors.push('Spell slots max must be a non-negative number');
  }
}

// Return validation result
if (validationErrors.length > 0) {
  return {
    json: {
      valid: false,
      errors: validationErrors,
      characterId: characterData.characterId
    }
  };
}

return {
  json: {
    valid: true,
    characterData,
    characterId: characterData.characterId
  }
};
